// jarvisClient.js — talks to the real Jarvis assistant running serverless.
//
// The backend is a FastAPI app in the JarvisAssistant repo, deployed as its own
// Vercel project. It streams Server-Sent Events describing a turn: the answer
// arriving as text deltas, and each tool call as it starts and finishes.
//
// EventSource cannot POST, and the prompt plus history has to go in a body, so
// this reads the stream off `fetch` manually. That also gives us AbortController
// for cancellation, which EventSource does not offer.
//
// Every transport (live now, recorded replay later) resolves to the same event
// schema, so the UI only ever learns one vocabulary:
//
//   status | text | thinking | tool_start | tool_result | failover | done | error

// The deployed Jarvis API — its own Vercel project, separate from this site.
// Override with REACT_APP_JARVIS_API to point at a local uvicorn during dev.
export const API_BASE =
  process.env.REACT_APP_JARVIS_API || "https://jarvis-live-beta.vercel.app";

// Full-capability ("Build") mode. By default it hits the SAME deployed backend
// as Explore — that server, deployed with JARVIS_FULL_MODE=1, answers the
// /api/build/* routes and spins the per-session sandbox. For local admin dev,
// override with REACT_APP_JARVIS_FULL_API=http://localhost:8000 in .env.local.
// (The old localhost default meant a *deployed* site tried to reach the
// visitor's own machine — which is what caused ERR_CONNECTION_REFUSED.)
export const FULL_API_BASE = process.env.REACT_APP_JARVIS_FULL_API || API_BASE;

export const ADMIN_TOKEN = process.env.REACT_APP_JARVIS_ADMIN_TOKEN || "";

const CLIENT_ID_KEY = "jarvis.demo.cid.v1";

// Stable per-browser id. The server hashes it together with the IP, so clearing
// localStorage alone does not reset the daily allowance.
export function clientId() {
  try {
    let id = localStorage.getItem(CLIENT_ID_KEY);
    if (!id) {
      id =
        typeof crypto !== "undefined" && crypto.randomUUID
          ? crypto.randomUUID()
          : `c-${Date.now()}-${Math.random().toString(36).slice(2)}`;
      localStorage.setItem(CLIENT_ID_KEY, id);
    }
    return id;
  } catch {
    // Private browsing with storage disabled — the IP half still applies.
    return "no-storage";
  }
}

// `?jarvis=live|replay` pins a transport, mirroring the `?cursor=off` escape
// hatch on the showcase page.
export function forcedTransport() {
  if (typeof window === "undefined") return null;
  const value = new URLSearchParams(window.location.search).get("jarvis");
  return value === "live" || value === "replay" ? value : null;
}

// ---------------------------------------------------------------------------
// RECORDINGS
//
// Real turns, captured against the live backend and replayed frame by frame at
// their recorded offsets — same event vocabulary, so the UI cannot tell the
// difference and does not need to. This is what the suggestion chips serve.
//
// The point is not to fake a live call. It is that the three free live calls a
// visitor gets should be spent on questions they thought of themselves, not on
// the four buttons everybody clicks first. Every recorded turn is badged as
// recorded, with the date it ran.
//
// Regenerate with scripts/capture-jarvis-recordings.py.
// ---------------------------------------------------------------------------

const RECORDINGS_URL = `${process.env.PUBLIC_URL || ""}/jarvis/recordings.json`;

let recordingsPromise = null;

export function loadRecordings() {
  if (!recordingsPromise) {
    recordingsPromise = fetch(RECORDINGS_URL)
      .then((response) => (response.ok ? response.json() : null))
      .then((data) => (data && data.recordings) || [])
      .catch(() => []);
  }
  return recordingsPromise;
}

const sleep = (ms, signal) =>
  new Promise((resolve) => {
    if (ms <= 0) {
      resolve();
      return;
    }
    const timer = setTimeout(resolve, ms);
    signal?.addEventListener(
      "abort",
      () => {
        clearTimeout(timer);
        resolve();
      },
      { once: true }
    );
  });

/**
 * Replay a captured turn. Mirrors runTurn's contract exactly — same events,
 * same resolve-when-finished, same abort behaviour — so the caller runs one
 * code path for live and recorded turns.
 *
 * `speed` > 1 plays faster than the original. Thinking and tool latency are
 * the interesting parts, so the default is real time.
 */
export async function playRecording(recording, { onEvent, signal, speed = 1 }) {
  if (!recording || !Array.isArray(recording.frames)) {
    onEvent({ type: "error", code: "network", message: "Recording missing." });
    return;
  }

  let clock = 0;
  for (const frame of recording.frames) {
    if (signal?.aborted) return;
    const wait = Math.max(0, (frame.at - clock) / speed);
    if (wait > 0) await sleep(wait, signal);
    clock = frame.at;
    if (signal?.aborted) return;

    // The transport on a recorded status frame is informational — the caller
    // decides how to label the turn, and must not let a replay overwrite what
    // it knows about the live backend's health.
    onEvent(frame.ev);
  }
}

export async function health(timeoutMs = 4000) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const response = await fetch(`${API_BASE}/api/health`, {
      signal: controller.signal,
    });
    if (!response.ok) return null;
    return await response.json();
  } catch {
    return null;
  } finally {
    clearTimeout(timer);
  }
}

/**
 * Run one turn. Calls onEvent for each event; resolves when the stream ends.
 *
 * Errors are delivered as `{type:"error"}` events rather than thrown, because a
 * turn can fail halfway through after useful output has already been rendered —
 * the caller wants to keep what arrived and show why it stopped.
 */
export async function runTurn({ prompt, history = [], onEvent, signal }) {
  return streamTurn({
    url: `${API_BASE}/api/q`,
    body: { prompt, history, clientId: clientId() },
    onEvent,
    signal,
  });
}

/**
 * Full-capability ("Build") turn — the admin's unclamped agent. Same event
 * schema as runTurn, so the caller renders it identically; it just hits the
 * private/local server and sends the admin token.
 */
export async function runFullTurn({
  prompt,
  history = [],
  sid = null,
  onEvent,
  signal,
}) {
  return streamTurn({
    url: `${FULL_API_BASE}/api/build`,
    body: { prompt, history, sid, clientId: clientId() },
    headers: ADMIN_TOKEN ? { "X-Jarvis-Admin": ADMIN_TOKEN } : {},
    onEvent,
    signal,
    unreachableMessage:
      "Couldn't reach the Build server. Start the local Jarvis server, or check REACT_APP_JARVIS_FULL_API.",
  });
}

// Start a Build session. On a sandbox-capable server this spins a fresh microVM
// and returns its id; in admin-local mode sid is null (the local workspace is
// the session). Returns { ok, sid, mode, tree } or null on failure.
export async function createBuildSession() {
  // Spinning a microVM can take 10–30s; cap the wait so the UI never hangs
  // forever — on timeout it resolves to null and the UI offers a retry.
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 120000);
  try {
    const res = await fetch(`${FULL_API_BASE}/api/build/session`, {
      method: "POST",
      headers: { "Content-Type": "application/json", ...fullHeaders() },
      body: JSON.stringify({ clientId: clientId() }),
      signal: controller.signal,
    });
    if (!res.ok) {
      // 429 (quota) and 403 (kill-switch) carry a JSON body with a `code` and a
      // human message — surface them so the UI can show the right wall instead
      // of a generic failure.
      let info = {};
      try {
        info = await res.json();
      } catch {
        // non-JSON error body — fall through with just the status
      }
      return {
        ok: false,
        status: res.status,
        code: info.code,
        error: info.error,
        usage: info.usage,
      };
    }
    return await res.json();
  } catch (err) {
    return {
      ok: false,
      error: err.name === "AbortError" ? "timeout" : "network",
    };
  } finally {
    clearTimeout(timer);
  }
}

export async function stopBuildSession(sid) {
  if (!sid) return;
  try {
    await fetch(`${FULL_API_BASE}/api/build/stop`, {
      method: "POST",
      headers: { "Content-Type": "application/json", ...fullHeaders() },
      body: JSON.stringify({ sid }),
      keepalive: true,
    });
  } catch {
    // best-effort — the VM also reaps itself on its TTL
  }
}

// ---- Build workspace (admin/full server only) ----------------------------
// The IDE explorer + editor read the live workspace through these. Both fail
// soft (return null) so the UI can show an empty tree rather than throw.

function fullHeaders() {
  return ADMIN_TOKEN ? { "X-Jarvis-Admin": ADMIN_TOKEN } : {};
}

export async function fetchBuildTree(sid, signal) {
  try {
    const q = sid ? `?sid=${encodeURIComponent(sid)}` : "";
    const res = await fetch(`${FULL_API_BASE}/api/build/tree${q}`, {
      headers: fullHeaders(),
      signal,
    });
    if (!res.ok) return null;
    return await res.json();
  } catch {
    return null;
  }
}

export async function fetchBuildFile(path, sid, signal) {
  try {
    const q = sid ? `&sid=${encodeURIComponent(sid)}` : "";
    const res = await fetch(
      `${FULL_API_BASE}/api/build/file?path=${encodeURIComponent(path)}${q}`,
      { headers: fullHeaders(), signal }
    );
    if (!res.ok) return null;
    return await res.json();
  } catch {
    return null;
  }
}

async function streamTurn({
  url,
  body,
  headers = {},
  onEvent,
  signal,
  unreachableMessage = "Could not reach Jarvis.",
}) {
  let response;
  try {
    response = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json", ...headers },
      body: JSON.stringify(body),
      signal,
    });
  } catch (err) {
    onEvent({
      type: "error",
      code: "network",
      message: err.name === "AbortError" ? "Cancelled." : unreachableMessage,
    });
    return;
  }

  if (!response.ok || !response.body) {
    onEvent({
      type: "error",
      code: "network",
      message: `Jarvis returned ${response.status}.`,
    });
    return;
  }

  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";

  // SSE frames are separated by a blank line. A frame can straddle two chunks,
  // so the tail of the buffer is kept until its terminator arrives.
  while (true) {
    let chunk;
    try {
      chunk = await reader.read();
    } catch (err) {
      if (err.name !== "AbortError") {
        onEvent({ type: "error", code: "network", message: "Stream dropped." });
      }
      return;
    }
    if (chunk.done) break;

    buffer += decoder.decode(chunk.value, { stream: true });

    let split;
    while ((split = buffer.indexOf("\n\n")) !== -1) {
      const frame = buffer.slice(0, split);
      buffer = buffer.slice(split + 2);

      for (const line of frame.split("\n")) {
        if (!line.startsWith("data: ")) continue; // ": keepalive" comments
        try {
          onEvent(JSON.parse(line.slice(6)));
        } catch {
          // A malformed frame is not worth killing the turn over.
        }
      }
    }
  }
}
